function placement(frame, canvasWidth, canvasHeight) {
  const [x, y, w, h] = frame.rect, [px, py] = frame.pivot || [0.5, 1];
  const bodyHeight = frame.bodyBounds?.[3] || h;
  const halfWidth = Math.max(0, canvasWidth / 2 - 14);
  const leftExtent = px * w, rightExtent = (1 - px) * w;
  const scale = Math.min((canvasHeight - 56) / bodyHeight, leftExtent > 0 ? halfWidth / leftExtent : Infinity, rightExtent > 0 ? halfWidth / rightExtent : Infinity);
  return { x: canvasWidth / 2 - px * w * scale, y: canvasHeight - 20 - py * h * scale, width: w * scale, height: h * scale, scale, source: [x, y, w, h], groundY: canvasHeight - 20 };
}
